      de: "Das Koryo-Museum in Kaesong war ursprünglich die höchste konfuzianische Akademie der Koryo-Dynastie, bekannt als Songgyungwan. Der im 10. Jahrhundert gegründete Komplex besteht aus mehr als 20 historischen Gebäuden und beherbergt eine reiche Sammlung von Keramiken und buddhistischen Artefakten. Der friedliche Innenhof wird von über tausend Jahre alten Gingko- und Zelkovenbäumen beschattet. Es ist ein UNESCO-Weltkulturerbe.",
      hu: "A kaesongi Koryo Múzeum eredetileg a Koryo-dinasztia legmagasabb rangú konfuciánus akadémiája, a Songgyungwan volt. A 10. században alapított komplexum több mint 20 történelmi épületből áll, és kerámiák, valamint buddhista leletek gazdag gyűjteményét őrzi. Békés belső udvarát több mint ezer éves páfrányfenyők és zelkova fák árnyékolják be. Az UNESCO Világörökség része.",
      ro: "Muzeul Koryo din Kaesong a fost inițial cea mai înaltă academie confuciană a dinastiei Koryo, cunoscută sub numele de Songgyungwan. Complexul fondat în secolul al X-lea este format din peste 20 de clădiri istorice și găzduiește o bogată colecție de ceramică și artefacte budiste. Curtea sa pașnică este umbrită de arbori ginkgo și zelkova cu o vechime de peste o mie de ani. Este inclus în Patrimoniul Mondial UNESCO.",
      en: "The Koryo Museum in Kaesong was originally the highest Confucian academy of the Koryo Dynasty, known as Songgyungwan. Founded in the 10th century, the complex consists of more than 20 historical buildings and houses a rich collection of ceramics and Buddhist artifacts. Its peaceful courtyard is shaded by ginkgo and zelkova trees that are over a thousand years old. It is a UNESCO World Heritage site.",
      es: "El Museo de Koryo en Kaesong fue originalmente la academia confuciana más alta de la dinastía Koryo, conocida como Songgyungwan. El complejo, fundado en el siglo X, consta de más de 20 edificios históricos y alberga una rica colección de cerámicas y artefactos budistas. El tranquilo patio interior está sombreado por árboles de ginkgo y zelkova de más de mil años de antigüedad. Es Patrimonio de la Humanidad por la UNESCO.",
      pt: "O Museu de Koryo em Kaesong era originalmente a mais alta academia confuciana da dinastia Koryo, conhecida como Songgyungwan. Fundado no século X, o complexo consiste em mais de 20 edifícios históricos e abriga uma rica coleção de cerâmicas e artefactos budistas. O pátio interior tranquilo é sombreado por ginkgos e zelkovas com mais de mil anos. É Património Mundial da UNESCO.",
      fr: "Le musée de Koryo à Kaesong était à l'origine la plus haute académie confucéenne de la dynastie Koryo, connue sous le nom de Songgyungwan. Fondé au Xe siècle, le complexe se compose de plus de 20 bâtiments historiques et abrite une riche collection de céramiques et d'artefacts bouddhistes. La cour intérieure paisible est ombragée par des ginkgos et des zelkovas millénaires. Il est classé au patrimoine mondial de l'UNESCO.",
