      fr: ["Fondée en 992 comme le plus haut établissement d'enseignement.", "Abrite plus de 1 000 reliques historiques.", "Les ginkgos sont âgés de plus de 1 000 ans.", "Fait partie du patrimoine mondial de l'UNESCO à Kaesong."],
