      es: ["Construida originalmente entre 1391 y 1393.", "Parte de la antigua muralla de Kaesong.", "Destruida en la Guerra de Corea en 1950.", "Reconstruida en 1954.", "La campana cercana es una de las tres grandes campanas de Corea.", "La caligrafía de la puerta fue realizada por un famoso erudito de la época Koryo.", "Registrada como Tesoro Nacional de Corea del Norte nº 124."],
      pt: ["Construído originalmente entre 1391 e 1393.", "Parte da antiga muralha de Kaesong.", "Destruído na Guerra da Coreia em 1950.", "Reconstruído em 1954.", "O sino próximo é um dos três grandes sinos da Coreia.", "A caligrafia no portão foi feita por um famoso estudioso da época Koryo.", "Registado como Tesouro Nacional da Coreia do Norte n.º 124."],
      fr: ["Construite à l'origine entre 1391 et 1393.", "Fait partie de l'ancienne muraille de Kaesong.", "Détruite pendant la guerre de Corée en 1950.", "Reconstruite en 1954.", "La cloche située à proximité est l'une des trois grandes cloches de Corée.", "La calligraphie sur la porte a été réalisée par un célèbre érudit de l'époque Koryo.", "Enregistrée comme trésor national n° 124 de la Corée du Nord."],
