    coords: [126.4717, 37.9822],
    name: {
      de: "Grabmal des Königs Kongmin",
      hu: "Kongmin király sírja",
      ro: "Mormântul Regelui Kongmin",
      en: "Tomb of King Kongmin"},
    description: {
      de: "Das Grabmal des Königs Kongmin ist eines der am besten erhaltenen königlichen Mausoleen der Koryo-Dynastie, gelegen in Kaesong. Errichtet in den 1360er Jahren, ruhen hier König Kongmin und seine mongolische Prinzessin Noguk in Zwillingsgrabhügeln nebeneinander. Die Anlage besticht durch meisterhafte Steinschnitzereien, die Treppen und Plattformen säumen, und bietet einen herrlichen Blick über das umliegende Tal. Es entging Plünderungen, da die inneren Grabkammern extrem gut gesichert waren.",
      hu: "Kongmin király sírja a Koryo-dinasztia egyik legjobb állapotban fennmaradt királyi mauzóleuma, amely Kaesongban található. Az 1360-as években épült, és itt nyugszik Kongmin király és mongol hercegnője, Noguk, ikersírhantokban egymás mellett. A komplexum lenyűgöző kőfaragványaival büszkélkedhet, amelyek a lépcsőket és emelvényeket szegélyezik, és csodálatos kilátást nyújt a környező völgyre. Elkerülte a kifosztást, mivel a belső sírkamrák rendkívül jól voltak biztosítva.",
      ro: "Mormântul Regelui Kongmin este unul dintre cele mai bine conservate mausolee regale ale dinastiei Koryo, situat în Kaesong. Construit în anii 1360, aici se odihnesc regele Kongmin și prințesa sa mongolă Noguk, alături, în movile funerare gemene. Complexul impresionează prin sculpturi magistrale în piatră care căptușesc scările și platformele și oferă o vedere magnifică asupra văii înconjurătoare. A evitat jefuirea deoarece camerele funerare interioare erau extrem de bine securizate.",
      en: "The Tomb of King Kongmin is one of the best-preserved royal mausoleums of the Koryo Dynasty, located in Kaesong. Built in the 1360s, King Kongmin and his Mongolian princess Noguk rest here side by side in twin burial mounds. The complex impresses with masterful stone carvings lining the stairs and platforms and offers a magnificent view over the surrounding valley. It escaped looting because the inner burial chambers were extremely well secured.",
      es: "La tumba del rey Kongmin es uno de los mausoleos reales mejor conservados de la dinastía Koryo, situado en Kaesong. Erigido en la década de 1360, aquí descansan el rey Kongmin y su princesa mongola Noguk en túmulos gemelos situados uno al lado del otro. El complejo destaca por sus magistrales tallas de piedra que bordean escaleras y plataformas, y ofrece una magnífica vista sobre el valle circundante. Escapó a los saqueos gracias a que las cámaras funerarias interiores estaban extremadamente bien protegidas.",
      pt: "O túmulo do Rei Kongmin é um dos mausoléus reais mais bem preservados da dinastia Koryo, situado em Kaesong. Erguido na década de 1360, aqui descansam o Rei Kongmin e a sua princesa mongol Noguk em túmulos gémeos situados lado a lado. O complexo destaca-se pelas magistrais esculturas em pedra que bordejam escadas e plataformas, e oferece uma vista magnífica sobre o vale circundante. Escapou aos saques graças ao facto de as câmaras funerárias internas estarem extremamente bem protegidas.",
      fr: "La tombe du roi Kongmin est l'un des mausolées royaux les mieux préservés de la dynastie Koryo, situé à Kaesong. Érigé dans les années 1360, il abrite le roi Kongmin et sa princesse mongole Noguk dans des tumulus jumeaux côte à côte. Le site impressionne par ses sculptures sur pierre magistrales qui bordent les escaliers et les plates-formes, et offre une vue magnifique sur la vallée environnante. Il a échappé aux pillages car les chambres funéraires intérieures étaient extrêmement bien sécurisées.",
    },
